import { NextResponse } from 'next/server';
import { supabase } from '@/lib/supabase';

export async function GET(request: Request) {
    const { searchParams } = new URL(request.url);
    const userId = searchParams.get('userId');

    if (!userId) {
        return NextResponse.json({ error: "UserId é obrigatório" }, { status: 400 });
    }

    try {
        // 1. Fetch Profile Balances
        const { data: profile, error: profileError } = await supabase
            .from('profiles')
            .select('balance_available, balance_processing')
            .eq('id', userId)
            .single();

        if (profileError) throw profileError;

        // 2. Fetch Transactions
        const { data: transactions, error: txError } = await supabase
            .from('financial_transactions')
            .select('*')
            .eq('user_id', userId)
            .order('created_at', { ascending: false });

        if (txError) throw txError;

        // 3. Calculate "Total Sacado" from Liquidado transactions
        const { data: withdrawnData, error: withdrawError } = await supabase
            .from('financial_transactions')
            .select('amount')
            .eq('user_id', userId)
            .eq('status', 'Liquidado')
            .eq('type', 'Solicitação de Saque');

        if (withdrawError) throw withdrawError;

        const totalWithdrawn = Math.abs(withdrawnData?.reduce((acc, curr) => acc + Number(curr.amount), 0) || 0);

        return NextResponse.json({
            available: profile.balance_available || 0,
            processing: profile.balance_processing || 0,
            withdrawn: totalWithdrawn,
            transactions: transactions || []
        });

    } catch (error: any) {
        console.error("Erro ao buscar dados financeiros:", error);
        return NextResponse.json({ error: error.message }, { status: 500 });
    }
}

export async function POST(request: Request) {
    try {
        const { userId, amount, pixKey } = await request.json();

        if (!userId || !amount || !pixKey) {
            return NextResponse.json({ error: "Dados incompletos" }, { status: 400 });
        }

        // 1. Check available balance
        const { data: profile, error: profileError } = await supabase
            .from('profiles')
            .select('balance_available, balance_processing')
            .eq('id', userId)
            .single();

        if (profileError) throw profileError;

        if (Number(profile.balance_available) < Number(amount)) {
            return NextResponse.json({ error: "Saldo insuficiente" }, { status: 400 });
        }

        // 2. Start Transaction (Simulated via multiple operations since no actual multi-table transaction in simple API)
        // In a real app, this should be a stored procedure or a server-side transaction.

        // 2a. Move balance from available to processing
        const { error: updateProfileError } = await supabase
            .from('profiles')
            .update({
                balance_available: Number(profile.balance_available) - Number(amount),
                balance_processing: Number(profile.balance_processing || 0) + Number(amount)
            })
            .eq('id', userId);

        if (updateProfileError) throw updateProfileError;

        // 2b. Create transactional record
        const { error: txError } = await supabase
            .from('financial_transactions')
            .insert([{
                user_id: userId,
                type: 'Solicitação de Saque',
                description: `Saque via Pix para: ${pixKey}`,
                amount: -Number(amount),
                status: 'Processando',
                reference_type: 'Withdrawal'
            }]);

        if (txError) {
            // Rollback balance (not perfect but better than nothing)
            await supabase
                .from('profiles')
                .update({
                    balance_available: Number(profile.balance_available),
                    balance_processing: Number(profile.balance_processing || 0)
                })
                .eq('id', userId);
            throw txError;
        }

        return NextResponse.json({ success: true, message: "Solicitação de saque enviada com sucesso" });

    } catch (error: any) {
        console.error("Erro ao solicitar saque:", error);
        return NextResponse.json({ error: error.message }, { status: 500 });
    }
}
